import math

def is_power_of_p(n, p):
    """Checks if n is a positive integer power of p."""
    if n <= 0:
        return False
    if n == 1:
        # 1 = p^0. We assume powers must be >= 1 if a, b >= 1 and p > 2, so x >= 1 is usually implied.
        # For this specific problem, since a, b >= 1 and p > 2, a^(p-1) + b >= 1 + 1 = 2. 
        # So the resulting power must be >= 2.
        return False 

    while n > 1:
        if n % p != 0:
            return False
        n //= p
    return True

def search_p7(limit):
    solutions = []
    p = 7

    print(f"--- Starting search for p={p}, a, b <= {limit} ---")

    for a in range(1, limit + 1):
        for b in range(a, limit + 1):
            # Calculate the values
            N1 = a**(p-1) + b
            N2 = b**(p-1) + a

            # Check if N1 and N2 are powers of p=7
            is_n1_power = is_power_of_p(N1, p)
            is_n2_power = is_power_of_p(N2, p)

            if is_n1_power and is_n2_power:
                solutions.append((p, a, b, N1, N2))
                print(f"Found solution: ({p}, {a}, {b}). N1={N1} (7^x), N2={N2} (7^y)")
    return solutions

# Execute the search for p=7, with limit=15
found_solutions = search_p7(15)

print("\n--- Summary ---")
if found_solutions:
    for sol in found_solutions:
        print(sol)
else:
    print("No solutions found for p=7 and a, b <= 15.")
